export function assess(r){const late=Math.max(0,Math.round((Date.parse(r.eta)-Date.parse(r.due))/DAY));const slip=Math.max(0,Math.round((Date.parse(r.eta)-Date.parse(r.need))/DAY));const short=Math.max(0,r.ordered-r.confirmed);return {...r,late,slip,short,severity:slip||short?'Critical':late?'Watch':'On track'};}
export function parseCSV(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell='';}else cell+=c;}if(quoted)throw Error('Unclosed quoted field.');row.push(cell);if(row.some(x=>x.trim()))rows.push(row);const heads=rows.shift()?.map(x=>x.trim());const keys=['po','supplier','part','ordered','confirmed','due','eta','job','need','units'];if(!heads||keys.some(k=>!heads.includes(k)))throw Error('Use the template columns: '+keys.join(', '));if(!rows.length)throw Error('CSV has no order rows.');const seen=new Set();return rows.map((v,i)=>{const r=Object.fromEntries(heads.map((k,j)=>[k,(v[j]??'').trim()]));for(const k of keys)if(!r[k])throw Error(`Row ${i+2}: missing ${k}.`);for(const k of ['ordered','confirmed','units']){r[k]=Number(r[k]);if(!Number.isFinite(r[k])||r[k]<0||!Number.isInteger(r[k]))throw Error(`Row ${i+2}: ${k} must be a nonnegative integer.`);}for(const k of ['due','eta','need'])if(!/^\d{4}-\d{2}-\d{2}$/.test(r[k])||!Number.isFinite(Date.parse(r[k]))||new Date(r[k]).toISOString().slice(0,10)!==r[k])throw Error(`Row ${i+2}: invalid ${k} date.`);if(seen.has(r.po))throw Error(`Duplicate purchase order: ${r.po}`);seen.add(r.po);return r;});}
